```c
static void ns_free(Sdb *s, SdbList *list) {
    SdbListIter next;
    SdbListIter *it;
    int deleted;
    SdbNs *ns;
    if (!list || !s) {
        return;
    }
    if (in_list (list, s)) {
        return;
    }
    ls_append (list, s);
    ls_foreach (s->ns, it, ns) {
        deleted = 0;
        next.n = it->n;
        if (!in_list (list, ns)) {
            ls_delete (s->ns, it);
            free (ns->name);
            ns->name = NULL;
            deleted = 1;
            if (ns->sdb) {
