        if (!deleted) {
            sdb_free (ns->sdb);
            s->ns->free = NULL;
            ls_delete (s->ns, it);
        }
        free (ns);
        it = &next;
    }
    ls_free (s->ns);
    s->ns = NULL;
}
```

